                    "主线任务": ["1. 探索客厅找到隐藏的猎人手册", "2. 与队友完成角色身份确认", "3. 破解书房密码锁获取关键线索"], // 数组类型
                    "支线任务": "1. 帮助NPC修复损坏的通讯设备|||2. 收集3个隐藏的纪念品（已收集2/3）", // 字符串类型（原数组）
                    "极限任务": { step1: "1. 在10分钟内逃离起火的卧室", step2: "2. 不使用道具击败1只精英怪物（未完成）" } // 对象类型（原数组）
                },
                "直播间": { 
                    "房间名": ["[LIVE] 家中的猎人 - 新手教程"],
