                }
            }
        };
        async function getChatMessages(id) { return [{ data: mockData }]; } 
        function getCurrentMessageId() { return 'mock'; }
        console.warn("SillyTavern environment not detected. Using mock data for display.");
    }

    document.addEventListener('DOMContentLoaded', initDisplay);
</script>
