<script>
  function initializeCard() {
    const uniqueId = 'status-card-' + Date.now() + Math.random();
    const cardEl = document.querySelector('details.status-card:not([id])');
    if (!cardEl) return;
    cardEl.id = uniqueId;

    const currentCard = document.getElementById(uniqueId);
    if (!currentCard) return;

    const dataSourceEl = document.getElementById('status-data-source');
    if (!dataSourceEl) return;

    let data;
    try { data = JSON.parse(dataSourceEl.textContent || dataSourceEl.innerText); } 
    catch(e) { console.error("Tavern Helper: Data parsing failed.", e); return; }

    const header = currentCard.querySelector('.status-card-header');
    const infoBar = currentCard.querySelector('.info-bar');
    const charContainer = currentCard.querySelector('.char-container');

    if(header) header.textContent = data.title;

    if(infoBar) {
      infoBar.innerHTML = `
        <div class="info-item"><span class="info-item-text">${data.date}</span></div>
        <div class="info-item"><span class="info-item-text">${data.time}</span></div>
        <div class="info-item"><span class="info-item-text">${data.season}</span></div>
        <div class="info-item"><span class="info-item-text">${data.location}</span></div>
        <div class="info-item"><span class="info-item-text">${data.weather}</span></div>
      `;
    }

    const tagColorClasses = ['tag-color-1', 'tag-color-2', 'tag-color-3', 'tag-color-4'];
    const nameGradients = [
        { grad: 'var(--grad-1)', shadow: 'rgba(249, 164, 200, 0.5)' },
        { grad: 'var(--grad-2)', shadow: 'rgba(130, 233, 222, 0.5)' },
        { grad: 'var(--grad-3)', shadow: 'rgba(255, 126, 121, 0.5)' },
        { grad: 'var(--grad-4)', shadow: 'rgba(188, 161, 247, 0.5)' }
    ];

    const createCharDisplay = (name, wearingStr) => {
        const display = document.createElement('div');
        display.className = 'char-display';

        const nameEl = document.createElement('div');
        nameEl.className = 'char-name';
        nameEl.textContent = name;

        const randomGradient = nameGradients[Math.floor(Math.random() * nameGradients.length)];
        nameEl.style.backgroundImage = randomGradient.grad;
        nameEl.style.textShadow = `0 0 12px ${randomGradient.shadow}`;

        const wearingList = document.createElement('div');
        wearingList.className = 'wearing-list';
        wearingList.innerHTML = wearingStr.split('/')
            .map(item => {
                const randomColorClass = tagColorClasses[Math.floor(Math.random() * tagColorClasses.length)];
                return `<span class="wearing-item ${randomColorClass}">${item.trim()}</span>`;
            })
            .join('');

        display.appendChild(nameEl);
        display.appendChild(wearingList);
        return display;
    };

    if (charContainer) {
        const characterEntries = data.charactersStr.split('|');
        const entryRegex = /^\s*([^\[]+)\s*\[穿着：\s*([^\]]+)\]\s*$/;
        characterEntries.forEach(entry => {
            const match = entry.trim().match(entryRegex);
            if (match) {
                const [, name, wearingStr] = match;
                charContainer.appendChild(createCharDisplay(name.trim(), wearingStr));
            }
        });
    }

    const toggleButton = currentCard.querySelector('.toggle-collapse-btn');
    if (toggleButton && header) {
        const toggleDetails = (e) => { 
            if (e) e.preventDefault(); 
            currentCard.open = !currentCard.open; 
        };
        toggleButton.onclick = toggleDetails;
        header.onclick = toggleDetails;
        currentCard.addEventListener('toggle', () => {
            toggleButton.textContent = currentCard.open ? '收起场景状态' : '展开场景状态';
        });
    }
  }

  if (document.readyState === 'loading') { document.addEventListener('DOMContentLoaded', initializeCard); } 
  else { initializeCard(); }
</script>

</body>
</html>
