<body>

    <div id="button-container">
        <div id="particle-container"></div>
        <button id="writeToLorebookButton">进入剧本！</button>
        <div id="statusMessage" style="color: green;"></div>
    </div>

    <script>
    (function() {
        async function writeToLorebook() {
            const endTag = '</剧本详情>';
            const startTag = '<剧本详情>';

            if (typeof TavernHelper === 'undefined' || typeof getCurrentMessageId === 'undefined' || typeof getChatMessages === 'undefined' || typeof window.parent.document.querySelector === 'undefined') {
                document.getElementById('statusMessage').style.color = 'red';
                document.getElementById('statusMessage').innerText = '错误：SillyTavern API 未找到。请在正确的环境下运行。';
                return;
            }

            const statusMessage = document.getElementById('statusMessage');
            statusMessage.innerText = '正在执行数据传输...';
            statusMessage.style.color = 'var(--neon-blue)';

            try {
                const currentMessageId = getCurrentMessageId();
                if (currentMessageId === null) {
                    statusMessage.innerText = '无法定位数据流源头。';
                    statusMessage.style.color = 'var(--neon-red)';
                    return;
                }
                const messages = await getChatMessages(currentMessageId);
                const lastMessage = messages.length > 0 ? messages[messages.length - 1] : null;

                if (!lastMessage || !lastMessage.message) {
                    statusMessage.innerText = '未找到有效数据包。';
                    statusMessage.style.color = 'var(--neon-red)';
                    return;
                }

                const aiResponse = lastMessage.message;
                let characterCardContent = null;

                // 从末尾开始查找结束标签
                const lastEndTagIndex = aiResponse.lastIndexOf(endTag);
                // 如果找到了结束标签，再从它之前的位置开始查找开始标签
                const lastStartTagIndex = lastEndTagIndex !== -1 ? aiResponse.lastIndexOf(startTag, lastEndTagIndex) : -1;

                // 确保找到了成对的标签
                if (lastStartTagIndex !== -1 && lastEndTagIndex !== -1) {
                    characterCardContent = aiResponse.substring(lastStartTagIndex, lastEndTagIndex + endTag.length).trim();
                }

                if (characterCardContent) {
                    const bookName = '猎人游戏·完全重制版';
                    const entryName = '【当前剧本】';

                    const allEntries = await TavernHelper.getLorebookEntries(bookName);
                    const targetEntry = allEntries.find(entry => entry.comment === entryName);

                    if (targetEntry) {
                        await TavernHelper.setLorebookEntries(bookName, [{ uid: targetEntry.uid, content: characterCardContent }]);
                        statusMessage.innerText = '数据写入完成。世界书已更新。';
                        statusMessage.style.color = 'var(--neon-blue)';
                    } else {
                        statusMessage.innerText = `数据传输失败：目标世界书条目 [${entryName}] 未找到。`;
                        statusMessage.style.color = 'var(--neon-red)';
                    }
                } else {
                    statusMessage.innerText = "数据包解析失败：未找到闭合的 <剧本详情> 标签。";
                    statusMessage.style.color = 'var(--neon-red)';
                }
            } catch (error) {
                statusMessage.innerText = `传输中断：${error.message}`;
                statusMessage.style.color = 'var(--neon-red)';
                console.error('传输中断:', error);
            }
        }

        // 粒子生成函数
        function createParticle() {
            const particle = document.createElement('div');
            particle.className = 'particle';
            const size = Math.random() * 3 + 1;
            const x = Math.random() * window.innerWidth;
            const y = Math.random() * window.innerHeight;
            const dx = (Math.random() - 0.5) * 300;
            const dy = (Math.random() - 0.5) * 300;

            particle.style.width = `${size}px`;
            particle.style.height = `${size}px`;
            particle.style.left = `${x}px`;
            particle.style.top = `${y}px`;
            particle.style.setProperty('--dx', `${dx}px`);
            particle.style.setProperty('--dy', `${dy}px`);

            document.getElementById('particle-container').appendChild(particle);

            setTimeout(() => {
                particle.remove();
            }, 3000);
        }

        // 自动生成粒子的定时器
        setInterval(() => {
            const numParticles = 10;
            for (let i = 0; i < numParticles; i++) {
                createParticle();
            }
        }, 500);

        document.getElementById('writeToLorebookButton').addEventListener('click', async (event) => {
            const input = window.parent.document.querySelector('#send_textarea');
            const sendButton = window.parent.document.querySelector('#send_button, #send_but');

            await writeToLorebook();

            if (input && sendButton) {
                input.value = '【进入剧本！】';
                input.dispatchEvent(new Event('input', { bubbles: true }));
                sendButton.click();
            } else {
                console.error('无法定位聊天输入端口。');
            }
        });
    })();
    </script>
</body>
</html>
