<script>
    (function() {
        const canvas = document.getElementById('particle-container');
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        let particles = [];
        let animationFrameId;
        function resizeCanvas() {
            const container = canvas.parentElement;
            if (!container) return;
            canvas.width = container.offsetWidth;
            canvas.height = container.offsetHeight;
            particles = [];_initParticles();
        }
        window.addEventListener('resize', resizeCanvas, false);
        class Particle {
            constructor() {
                const container = canvas.parentElement;
                this.x = Math.random() * container.offsetWidth;
                this.y = Math.random() * container.offsetHeight;
                this.vx = (Math.random() - 0.5) * 0.3;
                this.vy = (Math.random() - 0.5) * 0.3;
                this.radius = Math.random() * 1.2 + 0.5;
                this.color = Math.random() > 0.5 ? 'rgba(129, 140, 248, 0.9)' : 'rgba(244, 114, 182, 0.9)';
            }
            update() { this.x += this.vx; this.y += this.vy; if (this.x < 0 || this.x > canvas.width) this.vx *= -1; if (this.y < 0 || this.y > canvas.height) this.vy *= -1; }
            draw() { ctx.beginPath(); ctx.arc(this.x, this.y, this.radius, 0, Math.PI * 2); ctx.fillStyle = this.color; ctx.fill(); }
        }
        function _initParticles() {
            const particleCount = Math.floor(canvas.width * canvas.height / 20000);
            for (let i = 0; i < Math.max(20, particleCount); i++) { particles.push(new Particle()); }
        }
        function animate() { ctx.clearRect(0, 0, canvas.width, canvas.height); particles.forEach(p => { p.update(); p.draw(); }); animationFrameId = requestAnimationFrame(animate); }
        resizeCanvas();animate();
    })();

    function switchTab(event, pageName) {
        document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
        document.querySelectorAll('.tab-button').forEach(b => b.classList.remove('active'));
        document.getElementById(pageName).classList.add('active');
        event.currentTarget.classList.add('active');
    }

    /**
     * 安全获取值的函数，支持各种数据类型
     * @param {*} obj - 要查询的对象
     * @param {string} path - 路径，如 'a.b.0'
     * @param {*} defaultValue - 默认值
     * @returns {*} 获取到的值或默认值
     */
    function SafeGetValue(obj, path, defaultValue = "N/A") {
        // 如果路径无效，直接返回默认值
        if (typeof path !== 'string' || path.trim() === '') return defaultValue;

        // 如果对象本身就是基本类型，直接返回
        if (obj === null || typeof obj !== 'object') {
            return obj !== undefined ? obj : defaultValue;
        }

        let keys = path.split('.');
        let current = obj;

        for (let i = 0; i < keys.length; i++) {
            // 如果当前值不是对象/数组，尝试获取其属性
            if (current === null || current === undefined) {
                return defaultValue;
            }

            // 处理数组索引
            const key = keys[i];
            if (Array.isArray(current)) {
                const index = parseInt(key, 10);
                if (!isNaN(index) && index >= 0 && index < current.length) {
                    current = current[index];
                } else {
                    // 索引无效，尝试将数组转为字符串
                    return current.join(', ') || defaultValue;
                }
            } 
            // 处理对象
            else if (typeof current === 'object' && current.hasOwnProperty(key)) {
                current = current[key];
            } 
            // 处理其他类型
            else {
                // 尝试将当前值转为字符串
                return String(current) || defaultValue;
            }
        }

        // 最终值处理
        if (current === undefined || current === null) {
            return defaultValue;
        }

        // 处理特殊类型
        if (typeof current === 'boolean') {
            return current ? '是' : '否';
        }

        // 处理数组
        if (Array.isArray(current)) {
            return current.length > 0 ? current[0] : defaultValue;
        }

        // 处理对象
        if (typeof current === 'object') {
            // 尝试获取对象的第一个属性值
            const values = Object.values(current);
            return values.length > 0 ? values[0] : defaultValue;
        }

        return current;
    }

    /**
     * 格式化文本，处理各种数据类型
     * @param {*} text - 要格式化的文本
     * @returns {string} 格式化后的HTML字符串
     */
    function formatWithSeparators(text) {
        // 处理null/undefined
        if (text === null || text === undefined) {
            return '（暂无数据）';
        }

        // 处理布尔值
        if (typeof text === 'boolean') {
            return text ? '是' : '否';
        }

        // 处理数组
        if (Array.isArray(text)) {
            return text.map(item => String(item).trim()).filter(l => l).join('<br>') || '（暂无数据）';
        }

        // 处理对象
        if (typeof text === 'object') {
            try {
                // 尝试将对象转为字符串数组
                const values = Object.values(text).map(v => String(v));
                return values.join('<br>') || '（对象数据）';
            } catch (e) {
                return '（对象数据）';
            }
        }

        // 处理字符串
        if (typeof text === 'string') {
            return text.split('|||').map(l => l.trim()).filter(l => l).join('<br>') || '（暂无数据）';
        }

        // 处理其他基本类型
        return String(text);
    }

    function updateHotnessEffect(hotValueString) {
        const container = document.getElementById('hot-value-container');
        if (!container) return;

        let numericValue = 0;
        // 确保处理的值是字符串
        const s = String(hotValueString || '0').toLowerCase();
        const numPart = parseFloat(s.replace(/,/g, ''));
        if (!isNaN(numPart)) {
            if (s.includes('b') || s.includes('g')) {
                numericValue = numPart * 1e9;
            } else if (s.includes('m')) {
                numericValue = numPart * 1e6;
            } else if (s.includes('k') || s.includes('w')) {
                numericValue = numPart * (s.includes('w') ? 1e4 : 1e3);
            } else {
                numericValue = numPart;
            }
        }

        container.classList.remove('hot-level-1', 'hot-level-2', 'hot-level-3', 'hot-level-4');
        if (numericValue >= 1e8) container.classList.add('hot-level-4');
        else if (numericValue >= 1e7) container.classList.add('hot-level-3');
        else if (numericValue >= 1e6) container.classList.add('hot-level-2');
        else if (numericValue >= 1e4) container.classList.add('hot-level-1');
    }

    async function initDisplay() {
        try {
            const messages = typeof getChatMessages === 'function' ? await getChatMessages(getCurrentMessageId()) : [];
            if (!messages || !messages[0] || !messages[0].data || !messages[0].data.stat_data) {
