                document.getElementById('status-script').innerText = SafeGetValue(status, '当前剧本', '未进入剧本');

                // 任务记录
                const mainTask = SafeGetValue(status, '主线任务', '');
                const sideTask = SafeGetValue(status, '支线任务', '');
                const limitTask = SafeGetValue(status, '极限任务', '');

                // 渲染主线任务
                if (String(mainTask).trim() && String(mainTask) !== '无') {
                    document.getElementById('status-main-task').innerHTML = formatWithSeparators(mainTask);
                } else {
                    document.getElementById('status-main-task').innerHTML = '<span class="task-empty">暂无主线任务</span>';
                }

                // 渲染支线任务
                if (String(sideTask).trim() && String(sideTask) !== '无') {
                    document.getElementById('status-side-task').innerHTML = formatWithSeparators(sideTask);
                } else {
                    document.getElementById('status-side-task').innerHTML = '<span class="task-empty">暂无支线任务</span>';
                }

                // 渲染极限任务
                if (String(limitTask).trim() && String(limitTask) !== '无') {
                    document.getElementById('status-limit-task').innerHTML = formatWithSeparators(limitTask);
                } else {
                    document.getElementById('status-limit-task').innerHTML = '<span class="task-empty">暂无极限任务</span>';
                }

            } else {
                // 数据缺失时的默认显示
                ['status-name', 'status-score', 'status-total-score', 'status-rank', 'status-script'].forEach(id => {
                    document.getElementById(id).innerText = "数据缺失";
                });
                document.getElementById('status-main-task').innerHTML = '<span class="task-empty">任务数据缺失</span>';
                document.getElementById('status-side-task').innerHTML = '<span class="task-empty">任务数据缺失</span>';
                document.getElementById('status-limit-task').innerHTML = '<span class="task-empty">任务数据缺失</span>';
            }
        } catch (error) {
            console.error(`状态栏加载出错: ${error.message}`, error);
            const container = document.querySelector('.status-container');
            if (container) container.innerHTML = `<div style='padding: 20px; color: red;'>状态栏加载出错: ${error.message}</div>`;
        }
    }

    // 模拟数据（包含各种数据类型用于测试）
    if (typeof getChatMessages === 'undefined' || typeof getCurrentMessageId === 'undefined') {
        const mockData = {
