        characterEntries.forEach(entry => {
            const match = entry.trim().match(entryRegex);
            if (match) {
                const [, name, wearingStr] = match;
                charContainer.appendChild(createCharDisplay(name.trim(), wearingStr));
            }
        });
    }

    const toggleButton = currentCard.querySelector('.toggle-collapse-btn');
    if (toggleButton && header) {
        const toggleDetails = (e) => { 
            if (e) e.preventDefault(); 
            currentCard.open = !currentCard.open; 
        };
        toggleButton.onclick = toggleDetails;
        header.onclick = toggleDetails;
        currentCard.addEventListener('toggle', () => {
            toggleButton.textContent = currentCard.open ? '收起场景状态' : '展开场景状态';
        });
    }
  }

  if (document.readyState === 'loading') { document.addEventListener('DOMContentLoaded', initializeCard); } 
  else { initializeCard(); }
</script>

</body>
</html>
